from collections import OrderedDict

def simulate_lru(capacity: int, ops: list[tuple]) -> list[int]:
    cache = OrderedDict()
    result = []

    def get(key):
        if key in cache:
            value = cache.pop(key)
            cache[key] = value
            result.append(value)
        else:
            result.append(-1)

    def put(key, value):
        if key in cache:
            cache.pop(key)
        cache[key] = value
        result.append(value)
        if len(cache) > capacity:
            oldest_key = next(iter(cache))
            cache.pop(oldest_key)

    for op in ops:
        if op[0] == 'get':
            get(op[1])
        elif op[0] == 'put':
            put(op[1], op[2])

    return result
