def normalize_unix_path(path: str) -> str:
    # Split the path by '/' and initialize stack for canonical path
    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)

    # Join the stack to form the canonical path
    return '/' + '/'.join(stack) if stack else '/'
