from typing import List

def allow_requests(timestamps: List[int], window: int, limit: int) -> List[bool]:
    if not timestamps or window <= 0 or limit <= 0:
        raise ValueError("Invalid input parameters")

    allowed = []
    request_count = 0
    start_window = 0

    for i, t in enumerate(timestamps):
        if i > 0 and timestamps[i-1] < t - window:
            start_window = i
            request_count = 0

        if request_count < limit:
            allowed.append(True)
            request_count += 1
        else:
            allowed.append(False)

        if i >= start_window + limit:
            request_count -= 1

    return allowed
