def extract_markdown_links(md: str) -> List[Tuple[str, str]]:
    import re

    def match_link(text: str) -> Tuple[str, str]:
        match = re.search(r'\[([^\]]+)\]\(([^)]+)\)', text)
        if match:
            return match.group(1), match.group(2)
        return '', ''

    links = []
    while True:
        start = md.find('[')
        if start == -1:
            break
        end = md.find(']', start)
        if end == -1:
            break
        url_start = md.find('(', end)
        if url_start == -1:
            break
        url_end = md.find(')', url_start)
        if url_end == -1:
            break
        label = md[end+1:url_start]
        url = md[url_start+1:url_end]
        links.append((label, url))
        md = md[url_end+1:]
    return links

