def rle_encode(s: str) -> str:
    if not s:
        return ''

    encoded_str = ''
    count = 1
    for i in range(1, len(s) + 1):
        if i < len(s) and s[i] == s[i - 1]:
            count += 1
        else:
            encoded_str += s[i - 1] + str(count)
            count = 1

    return encoded_str
