def topo_sort_tasks(deps: dict[str, list[str]]) -> list[str]:
    def dfs(task: str) -> bool:
        if visiting.add(task):
            for prereq in deps[task]:
                if prereq in visiting or (prereq in graph and not dfs(prereq)):
                    return False
            visiting.remove(task)
            visiting_order.append(task)
            return True
        return False

    graph = {task: set(prereqs) for task, prereqs in deps.items()}
    visiting = set()
    visiting_order = []

    for task in graph:
        if task not in visiting_order and not dfs(task):
            return []

    return visiting_order[::-1]

